import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

pub fn main() effect io -> Result<(), AppError> {
    let s = "payload"
    let m = conc.Mutex(0)
    let f: fn(Int64) -> Int64 = |v| v + s.byteLength()
    var acc: Int64 = 0
    var i: Int64 = 0
    while i < 60000 {
        let c = Cell { n: i }
        acc = acc + c.n
        i = i + 1
    }
    var n: Int64 = 0
    n = m.update(f)
    io.println("${s}:${n}:${acc}")
    return Ok(())
}
